from pathlib import Path
import json,base64,shutil,hashlib
import os
ROOT=Path(__file__).resolve().parents[3];OUT=Path(os.environ.get('SPOTLIGHT_CATALOGUE_OUT',str(ROOT/'build/choice-catalogue-review')));OUT.mkdir(parents=True,exist_ok=True)
styles=[
('00','Focus Studio','Referencia de los componentes actuales','Glass sobrio y acentos por aplicación.','Conservarlo también es una elección válida.','C'),
('01','Carbon','Compacto y directo','Más lista visible, inspector estrecho y marcos discretos.','Menos protagonismo de tarjetas y espacios de descanso.','01'),
('02','Pearl','macOS suave','Superficies claras, capas definidas y bordes amplios.','Los marcos consumen algo más de espacio.','02'),
('03','Ink','Monocromo contundente','Negro profundo, separación simple y acento violeta.','El contraste puede sentirse más duro en oscuro.','03'),
('04','Editorial','Tipográfico y cálido','Títulos serif, ritmo pausado y composición de lectura.','Se aleja más de Geist y del carácter de herramienta rápida.','04'),
('05','Nordic','Detalle debajo de la lista','Resultados arriba e inspector debajo, sin dos columnas laterales.','Más recorrido vertical; cambiaría el hábito del inspector lateral.','05'),
('06','Terminal','Técnico y funcional','Monoespaciada, esquinas rectas y precisión visual.','Algunos títulos ocupan más ancho; estética más especializada.','06'),
('07','Tonal','Tarjetas de resultados','Resultados en dos columnas en tablet, con tarjetas tonales.','Puede reducir el escaneo lineal; sólo sería una decisión visual posterior.','07'),
('08','Navigator','Lista primero','Más ancho para títulos, inspector secundario y marco contenido.','El inspector gana menos espacio para contenido largo.','08'),
('09','Copper','Cálido y sobrio','Tonos cobre, superficies tostadas y acentos contenidos.','El tono cálido cambia bastante la identidad cromática.','09'),
('10','Pop','Inspector primero','Inspector a la izquierda, lista a la derecha y selección expresiva.','Invierte el recorrido de lectura habitual; exige elección explícita.','10'),
('11','Titanium','Profesional y estructurado','Bordes finos, gris frío y alta densidad ordenada.','Se percibe más rígido y técnico.','11'),
('12','Paper','Plano y de lectura','Superficies marfil, esquinas rectas y mínimo ornamento.','Menos efecto glass y más espacio entre resultados.','12')]
S=[dict(id='E'+a,name=b,tag=c,benefit=d,tradeoff=e,direction=f) for a,b,c,d,e,f in styles]
F=json.loads((ROOT/'app/src/test/resources/choice-catalogue/functions.json').read_text())
imgs={}
for p in sorted((Path(__file__).resolve().parent/'screenshots').rglob('*.png')):
 key=str(p.relative_to(Path(__file__).resolve().parent/'screenshots'));imgs[key]='data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
assert len(imgs)==348,len(imgs)
(OUT/'catalogo.json').write_text(json.dumps({'styles':S,'functions':F,'source_head':'dd5e595a58593dd0226ed2ac5edf9d14914fd252','screenshots':348,'production_changes':False},ensure_ascii=False,indent=2)+'\n')
DATA=json.dumps({'styles':S,'functions':F,'images':imgs},ensure_ascii=False)
html=r'''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Elegí tu Spotlight · 12 estilos y 36 funciones</title>
<style>
:root{color-scheme:dark;--bg:#101216;--card:#1c2027;--line:#343c49;--text:#f1f3f5;--muted:#b5becc;--accent:#b8d8ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.5 system-ui,sans-serif}header,main,footer{max-width:1440px;margin:auto;padding:28px}h1{font-size:clamp(32px,5vw,64px);line-height:1.05;letter-spacing:-.045em;margin:18px 0}h2{font-size:28px}h3{margin:10px 0;font-size:23px}p{margin:8px 0}button,select,a.link{border:1px solid #505c70;border-radius:10px;background:#252d39;color:var(--text);padding:10px 14px;font:inherit;cursor:pointer;min-height:44px}button:hover,a.link:hover{border-color:#d3e5ff}button[aria-pressed=true],button.chosen{background:#b8d8ff;color:#121822;border-color:#b8d8ff}button:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #f5c77b;outline-offset:3px}.pill{font-size:12px;font-weight:700;letter-spacing:.06em;padding:5px 9px;border-radius:6px;background:#303a49;display:inline-block}.muted{color:var(--muted)}.lead{max-width:850px;font-size:19px}.notice{border-left:3px solid #9fbdde;padding:10px 18px;background:#1c2530;border-radius:4px;margin:20px 0}.toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.sticky{position:sticky;top:0;background:#101216f5;border-block:1px solid var(--line);padding:16px 28px;z-index:5}.sticky>div{max-width:1384px;margin:auto}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.card{border:1px solid var(--line);background:var(--card);border-radius:18px;overflow:hidden;min-width:0}.card header{padding:20px}.card img{width:100%;display:block;background:#12151a;object-fit:contain}.preview{border:0;padding:0;width:100%;background:#15171d;cursor:zoom-in;display:block;border-radius:0}.preview img{max-height:480px}.card-body{padding:20px}.meta{font-size:14px;color:var(--muted)}.card .toolbar{margin-top:18px}.function-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.function-card{padding:22px}.function-card h3{font-size:20px}.query{font:15px/1.4 ui-monospace,monospace;background:#11161d;padding:13px;border-radius:8px;margin:16px 0;color:#d8e9ff}.limit{font-size:14px;color:#e1cbb4}.section-head{display:flex;justify-content:space-between;gap:20px;align-items:baseline;margin:24px 0}.selection{padding:24px;background:#1e2b39;border-radius:14px;margin:26px 0}textarea{width:100%;background:#0e151d;color:#d9e8fb;border:1px solid #5b6e83;border-radius:10px;min-height:110px;padding:15px;font:16px/1.5 system-ui}dialog{background:#15191f;color:var(--text);border:1px solid #5d6e84;border-radius:15px;padding:22px;width:min(1320px,96vw);max-height:94vh}dialog::backdrop{background:#000c}.dialog-head{display:flex;justify-content:space-between;gap:20px;align-items:center;position:sticky;top:-22px;background:#15191f;padding:12px 0}.compare{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.compare img,.single img{width:100%;height:auto}.single{max-width:1050px;margin:auto}.hidden{display:none!important}a{color:#bbd8ff;overflow-wrap:anywhere}.count{font-weight:700}.tiny{font-size:12px}details{margin-top:14px}summary{cursor:pointer}.footer{border-top:1px solid var(--line);margin-top:30px}.colorbar{height:3px;background:linear-gradient(90deg,#b7d5ff,#b393d8,#d5b080)}
@media(max-width:900px){.function-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.grid{grid-template-columns:1fr}}@media(max-width:560px){header,main,footer{padding:20px}.sticky{padding:12px 20px}.function-grid,.compare{grid-template-columns:1fr}button,select{font-size:14px}.lead{font-size:17px}.section-head{display:block}h1{font-size:39px}}
</style>
<header><span class="pill">SPOTLIGHT NEXT · CATÁLOGO PARA ELEGIR</span><h1>Que se vea como querés.<br>Que sirva para lo que hacés.</h1><p class="lead">12 direcciones estéticas + Focus actual de referencia. 36 mejoras funcionales viables. Mirá, compará y marcá lo que te guste; no se cambia nada en tu aplicación.</p><div class="notice"><b>348 capturas de Compose reales.</b> Son prototipos de presentación en un laboratorio JVM/API33 con datos ficticios. No son imágenes de IA ni capturas de una APK instalada. Las fichas funcionales ilustran propuestas; no prueban que esas capacidades estén implementadas.</div><p class="muted">Podés combinar la barra de un estilo, los resultados de otro y las funciones que quieras. Elegir no autoriza automáticamente una implementación sensible.</p></header>
<nav class="sticky"><div class="toolbar"><button id="tabStyles" aria-pressed="true">01 · Estéticas</button><button id="tabFunctions" aria-pressed="false">02 · Funciones</button><button id="goSelection">Mi selección <span class="count" id="count">0</span></button></div></nav>
<main><section id="styles"><div class="section-head"><h2>Elegí una dirección, no sólo un color</h2><button id="compareChosen">Comparar dos marcadas</button></div><div class="toolbar"><label>Tamaño <select id="device"><option value="tablet">Tablet · 1000 dp</option><option value="phone">Teléfono · 390 dp</option><option value="compact">Compacto · 330 dp · texto 200%</option></select></label><label>Tema <select id="theme"><option value="dark">Oscuro</option><option value="light">Claro</option></select></label><label>Escena <select id="scene"><option value="inspector">Resultados + inspector</option value="inicio"><option value="inicio">Inicio</option><option value="resultados">Búsqueda</option><option value="acciones">Acciones</option><option value="ajustes">Ajustes</option></select></label></div><p class="meta">Mismo lienzo, consulta, datos y selección. El tamaño interior y el reparto lista/inspector varían intencionalmente por estilo. En 200% se muestran inspector y acciones. Sin blur costoso. No son mediciones de rendimiento en tu tablet.</p><div id="styleGrid" class="grid" style="margin-top:24px"></div></section>
<section id="functions" class="hidden"><div class="section-head"><h2>36 funciones que sí tienen un camino técnico</h2></div><p class="lead">No todo requiere inteligencia artificial. Muchas mejoras aprovechan motores locales y APIs públicas que ya están en el proyecto.</p><div class="notice">“Ampliación” = existe una base, falta completar o pulir el recorrido propuesto. “Nueva acotada” = implementación nueva de alcance limitado. “Condicional” = depende de permisos, motor o aceptación física; no se vende como lista para usar.</div><div class="toolbar"><label>Área <select id="group"><option value="">Todas</option></select></label><label>Estado <select id="status"><option value="">Todos</option><option>Ampliación</option><option>Nueva acotada</option><option>Condicional</option></select></label></div><div class="function-grid" id="functionGrid" style="margin-top:24px"></div></section>
<section id="selection" class="selection"><h2>Tu selección</h2><p>Marcá favoritos. Después podés copiar este resumen y mandármelo en el chat. No se transmite nada desde esta página.</p><textarea id="selectionText" readonly></textarea><div class="toolbar"><button id="copy">Copiar resumen</button><button id="export">Guardar selección JSON</button><button id="reset">Vaciar selección</button></div><p id="copyStatus" class="meta" role="status"></p></section>
</main><footer class="footer"><p><b>Qué está comprobado:</b> los componentes Compose se dibujaron y las capturas se generaron en pruebas aisladas sin despachar acciones. El código productivo, ranking, datos, preferencias y Preview69 no se modificaron.</p><p class="muted">API33/Robolectric; dimensiones de laboratorio, no Galaxy/Motorola reales. IME, rotación, talkback, contraste completo y fluidez de cada dirección requieren validación posterior. Las propuestas no están aprobadas ni instaladas.</p></footer>
<dialog id="dialog"><div class="dialog-head"><h2 id="dialogTitle"></h2><button id="closeDialog" autofocus>Cerrar</button></div><div id="dialogContent"></div></dialog>
<script id="data" type="application/json">__DATA__</script>
<script>
const D=JSON.parse(document.querySelector('#data').textContent),$=s=>document.querySelector(s);let chosen={styles:[],functions:[]};try{chosen=JSON.parse(localStorage.getItem('spotlight-choice-v1'))||chosen}catch(e){}
function esc(x){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function profile(){return $('#device').value+'-'+$('#theme').value}function scene(){let s=$('#scene').value;if($('#device').value==='compact'&&!['inspector','acciones'].includes(s)){$('#scene').value='inspector';s='inspector'}return s}
function src(st){return D.images[profile()+'-'+scene()+'-'+st.direction+'.png']}
function mark(type,id){let a=chosen[type];chosen[type]=a.includes(id)?a.filter(x=>x!==id):[...a,id];save();renderStyles();renderFunctions()}
function save(){try{localStorage.setItem('spotlight-choice-v1',JSON.stringify(chosen))}catch(e){}$('#count').textContent=chosen.styles.length+chosen.functions.length;$('#selectionText').value='Estéticas: '+(chosen.styles.join(', ')||'sin elegir')+'\nFunciones: '+(chosen.functions.join(', ')||'sin elegir')+'\nTambién puedo combinar componentes de varias direcciones.'}
function modal(title,html){$('#dialogTitle').textContent=title;$('#dialogContent').innerHTML=html;$('#dialog').showModal()}
function compare(ids){const rows=ids.map(id=>D.styles.find(s=>s.id===id));modal('Comparación · mismas condiciones','<div class="compare">'+rows.map(s=>'<div><h3>'+esc(s.id+' · '+s.name)+'</h3><img src="'+src(s)+'" alt="Captura Compose '+esc(s.name)+'"><p>'+esc(s.benefit)+'</p><p class="muted">'+esc(s.tradeoff)+'</p></div>').join('')+'</div>')}
function renderStyles(){for(const o of $('#scene').options)o.disabled=$('#device').value==='compact'&&! ['inspector','acciones'].includes(o.value);$('#styleGrid').innerHTML=D.styles.map(s=>`<article class="card"><div class="card-body"><span class="pill">${s.id} ${s.id==='E00'?'· REFERENCIA':''}</span><h3>${s.name}</h3><p class="muted">${s.tag}</p></div><button class="preview" data-view="${s.id}" aria-label="Ampliar ${s.name}"><img loading="lazy" src="${src(s)}" alt="Prototipo Compose ${s.name} · ${profile()} · ${scene()}"></button><div class="card-body"><p>${s.benefit}</p><p class="meta">A considerar: ${s.tradeoff}</p><div class="toolbar"><button data-style="${s.id}" class="${chosen.styles.includes(s.id)?'chosen':''}" aria-pressed="${chosen.styles.includes(s.id)}">${chosen.styles.includes(s.id)?'Marcada':'Me interesa'}</button><button data-base="${s.id}">Comparar con actual</button></div></div></article>`).join('');document.querySelectorAll('[data-style]').forEach(b=>b.onclick=()=>mark('styles',b.dataset.style));document.querySelectorAll('[data-base]').forEach(b=>b.onclick=()=>compare(['E00',b.dataset.base]));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{let s=D.styles.find(s=>s.id===b.dataset.view);modal(s.id+' · '+s.name,'<div class="single"><img src="'+src(s)+'" alt="Captura completa"><p>'+esc(s.benefit)+'</p><p class="muted">'+esc(s.tradeoff)+'</p></div>')})}
function renderFunctions(){let fs=D.functions.filter(f=>(!$('#group').value||f.group===$('#group').value)&&(!$('#status').value||f.status.startsWith($('#status').value)));$('#functionGrid').innerHTML=fs.map(f=>`<article class="card function-card"><span class="pill">${f.id} · ${f.status}</span><h3>${f.title}</h3><p>${f.value}</p><div class="query">${esc(f.example)}<br>↓<br>${esc(f.result)}</div><p class="limit">${f.limit}</p><p class="meta">Esfuerzo relativo: ${f.effort}. Estimación, no plazo prometido.</p><details><summary>Por qué es viable</summary><p class="meta">Base existente o punto de extensión inspeccionado:</p><a class="tiny" target="_blank" rel="noopener" href="https://github.com/bauti3311-sys/Spotlight-Next/blob/dd5e595a58593dd0226ed2ac5edf9d14914fd252/${f.source}">${f.source.split('/').pop()}</a><p class="meta">Sin implementar esta propuesta ni activar permisos. El alcance final se define después de elegir.</p></details><div class="toolbar"><button data-function="${f.id}" class="${chosen.functions.includes(f.id)?'chosen':''}" aria-pressed="${chosen.functions.includes(f.id)}">${chosen.functions.includes(f.id)?'Marcada':'Me interesa'}</button><button data-demo="${f.id}">Ver ejemplo Compose</button></div></article>`).join('');document.querySelectorAll('[data-function]').forEach(b=>b.onclick=()=>mark('functions',b.dataset.function));document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>{let f=D.functions.find(f=>f.id===b.dataset.demo);modal(f.id+' · '+f.title,'<div class="single"><img src="'+D.images['functions/'+f.id+'.png']+'" alt="Ejemplo visual de propuesta, no función ejecutada"><p>'+esc(f.limit)+'</p></div>')})}
$('#tabStyles').onclick=()=>tab(false);$('#tabFunctions').onclick=()=>tab(true);function tab(f){$('#styles').classList.toggle('hidden',f);$('#functions').classList.toggle('hidden',!f);$('#tabStyles').setAttribute('aria-pressed',!f);$('#tabFunctions').setAttribute('aria-pressed',f)}
for(const x of ['device','theme','scene'])$('#'+x).onchange=renderStyles;for(const g of [...new Set(D.functions.map(f=>f.group))])$('#group').add(new Option(g,g));$('#group').onchange=renderFunctions;$('#status').onchange=renderFunctions;$('#closeDialog').onclick=()=>$('#dialog').close();$('#compareChosen').onclick=()=>{if(chosen.styles.length<2){$('#copyStatus').textContent='Marcá al menos dos estéticas para compararlas.';$('#selection').scrollIntoView({behavior:'smooth'});return}compare(chosen.styles.slice(-2))};$('#goSelection').onclick=()=>$('#selection').scrollIntoView({behavior:'smooth'});$('#copy').onclick=()=>{$('#selectionText').select();document.execCommand('copy');$('#copyStatus').textContent='Resumen seleccionado y copiado, si tu navegador lo permite.'};$('#reset').onclick=()=>{chosen={styles:[],functions:[]};save();renderStyles();renderFunctions()};$('#export').onclick=()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(chosen,null,2)],{type:'application/json'}));a.download='Mi-eleccion-Spotlight.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};save();renderStyles();renderFunctions();
</script></html>'''
html=html.replace('</option value="inicio"><option value="inicio">','</option><option value="inicio">')
(OUT/'Elegir-Spotlight.html').write_text(html.replace('__DATA__',DATA))
print('Self-contained gallery:',(OUT/'Elegir-Spotlight.html').stat().st_size,'bytes')
